+static void radix_pass(uint32_t* input, uint32_t* output, size_t n, int pass) {
+    // Counting phase
+    uint32_t count[256];
+    std::memset(count, 0, sizeof(count));
+    int shift = pass * 8;
+
+    size_t i = 0;
+    // Process 4 elements at a time
+    for (; i + 3 < n; i += 4) {
+        uint32_t key0 = (input[i] >> shift) & 0xFF;
+        uint32_t key1 = (input[i+1] >> shift) & 0xFF;
+        uint32_t key2 = (input[i+2] >> shift) & 0xFF;
+        uint32_t key3 = (input[i+3] >> shift) & 0xFF;
+        count[key0]++;
+        count[key1]++;
+        count[key2]++;
+        count[key3]++;
+    }
+    // Handle remainder
+    for (; i < n; ++i) {
+        uint32_t key = (input[i] >> shift) & 0xFF;
+        count[key]++;
+    }
+
+    // Prefix sum phase (calculating starting positions)
+    size_t sum = 0;
+    for (int i = 0; i < 256; ++i) {
+        size_t current_count = count[i];
+        size_t prev_sum = sum;
+        sum += current_count;
+        count[i] = prev_sum; 
+    }
+
+    // Distribution phase
+    for (size_t i = 0; i < n; ++i) {
+        uint32_t key = (input[i] >> shift) & 0xFF;
+        output[count[key]++] = input[i];
+    }
 }

 extern "C" void sort_u32(uint32_t* a, size_t n) {
-    std::vector<uint32_t> tmp(n);
-    merge_sort_rec(a, tmp.data(), 0, n);
+    if (n <= 1) return;
+
+    // O(N) check for already sorted input
+    bool already_sorted = true;
+    for (size_t i = 0; i < n - 1; ++i) {
+        if (a[i] > a[i+1]) {
+            already_sorted = false;
+            break;
+        }
+    }
+    if (already_sorted) return;
+
+    // Allocate scratch buffer
+    std::vector<uint32_t> tmp(n); 
+    
+    // 4 passes of 8 bits (32 bits total)
+    // P=0: a -> tmp
+    radix_pass(a, tmp.data(), n, 0);
+    // P=1: tmp -> a
+    radix_pass(tmp.data(), a, n, 1);
+    // P=2: a -> tmp
+    radix_pass(a, tmp.data(), n, 2);
+    // P=3: tmp -> a
+    radix_pass(tmp.data(), a, n, 3);
 }
